<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><h2>Admission Applications</h2><div class="d-flex gap-2"><a class="btn btn-outline-success" href="<?= base_url('school/admission/reports/applications.csv').($status?'?status='.urlencode($status):'') ?>">Export CSV</a><form method="get"><select class="form-control" name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(\App\Modules\admission\Models\AdmissionApplicationModel::STATUSES as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= ucwords(str_replace('_',' ',$s)) ?></option><?php endforeach ?></select></form></div></div>
<div class="card shadow-sm"><div class="card-body table-responsive"><table class="table table-hover"><thead><tr><th>Application</th><th>Student</th><th>School</th><th>Class</th><th>Mobile</th><th>Payment</th><th>Status</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><a href="<?= base_url('school/admission/applications/'.$item->token) ?>"><?= esc($item->application_no) ?></a><br><small><?= esc($item->submitted_at) ?></small></td><td><?= esc($item->student_name) ?></td><td><?= esc($item->school_name) ?></td><td><?= esc($item->class_name) ?></td><td><?= esc($item->guardian_mobile) ?></td><td><?= esc(ucwords(str_replace('_',' ',$item->payment_status))) ?></td><td><span class="badge bg-secondary"><?= esc(ucwords(str_replace('_',' ',$item->application_status))) ?></span></td></tr><?php endforeach ?><?php if(!$items): ?><tr><td colspan="7" class="text-center text-muted">No applications found.</td></tr><?php endif ?></tbody></table></div></div></div>
